	flag := func(e ast.Expr) {
		out = append(out, filepath.ToSlash(path)+":"+strconv.Itoa(fset.Position(e.Pos()).Line))
	}
	tea := importsBubbletea(file)
	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.CaseClause:
			for _, e := range x.List {
				if isSpaceLiteral(e) {
