func TestLaunchFormEnterNeverTogglesACheckbox(t *testing.T) {
	for _, cb := range launchCheckboxes() {
		t.Run(cb.name, func(t *testing.T) {
			f := newKeysForm()
			field := cb.field(f)
			focusLaunchField(f, field)
			start := cb.get(f)

			f, _ = f.Update(testutil.Key("enter"))
